   946  bool IsValidVersionTag(uint32_t tag) {
   947    return tag == 0x000010000 ||
   948           // OpenType fonts with CFF data have 'OTTO' tag.
   949           tag == OTS_TAG('O','T','T','O') ||
   950           // Older Mac fonts might have 'true' or 'typ1' tag.
   951           tag == OTS_TAG('t','r','u','e') ||
   952           tag == OTS_TAG('t','y','p','1');
